// 热执行必须还在原实际会话；冷源永久绑定原claim和本人作者答复，不靠今日会话存在。
#include "visit_reply_authored.hpp"
#include "visit_reply_detail.hpp"
#include "visit_reply_life.hpp"
namespace hanmo::resident {namespace {
struct Source {const VisitReplyIntent* intent=nullptr;const VisitReceptionIntent* reception=nullptr;const VisitReplyPolicy* policy=nullptr;const VisitMessagePolicy* original=nullptr;};
Source source(const VisitReplyAuthorshipRead& read,const VisitReplyCatalog& replies,const VisitMessageCatalog& messages,const StableId& id){Source s;s.intent=visit_reply_intent(read.intents,id);s.reception=s.intent?visit_reception_intent(read.reception,s.intent->reception_intent_id):nullptr;s.policy=s.intent?visit_reply_detail::policy(replies,s.intent->reply_policy_id):nullptr;s.original=s.policy?visit_reply_detail::original(messages,s.policy->message_policy_id):nullptr;return s;}
Status claim(const CommonStore& common,const VisitReplyAuthorshipRead& read,const Source& s,const StableId& actor,const StableId& id,const VisitMessageContact& contact){const auto* c=read.claims.claims.find(id);const auto* h=common.state().facts.find(id);if(!s.intent||!s.reception||!s.original||s.reception->purpose!="receive"||s.reception->actor_id!=actor||s.original->recipient_actor_id!=actor||s.reception->message_policy_id!=s.original->id||!c||c->fact_id!=id||!h||h->id!=id||h->kind!=visit_reception_claim_kind||h->domain!=visit_reception_claim_module||c->actor_id!=actor||c->intent_id!=s.reception->id||c->policy_id!=s.original->id||c->session_id!=contact.session_id||c->provider_actor_id!=s.original->custodian_actor_id||c->role_id!=contact.role_id||c->dialogue_id!=contact.dialogue_id||c->place_id!=contact.place_id||c->tick>contact.tick||read_visit_reception_claim(read.claims,contact.session_id,actor,s.reception->id)!=c)return common_failure("VisitReplyAuthoredClaimRequired",id);return common_success();}
}
Outcome<AuthoredVisitReplyQuote> preview_authored_visit_reply(const CommonStore& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitReplyCatalog& replies,const VisitReplyState& state,const VisitReplyAuthorshipRead& read,const StableId& actor,const AuthoredVisitReply& command){
    if(actor==common.state().metadata.player_actor_id)return {false,{},common_failure("VisitReplyAuthoredNpcRequired").error};
    if(!visit_reply_authored_version(state.version)||state.version!=replies.version)return {false,{},common_failure("VisitReplyAuthoredVersionRequired").error};auto valid=validate_visit_reply_intents(read.intents,replies,read.reception,originals,definitions);if(!valid.ok)return {false,{},valid.error};const auto s=source(read,replies,originals,command.intent_id);if(!s.intent||!s.reception||s.reception->actor_id!=actor)return {false,{},common_failure("VisitReplyAuthoredIntentRequired").error};
    VisitReplyCommand request=ReplyVisitMessage{s.intent->reply_policy_id,command.message_fact_id,s.intent->response};auto reply=preview_visit_reply(common,messages,originals,read.interactions,definitions,access,replies,state,actor,request,read.life);if(!reply.ok)return {false,{},reply.error};if(reply.value.received_fact_id!=command.received_fact_id)return {false,{},common_failure("VisitReplyAuthoredReceivedSourceRequired").error};const auto contact=visit_reply_detail::contact(reply.value.source,reply.value.actual_quoted_at?reply.value.actual_quoted_at->half_day_tick:common.tick());valid=claim(common,read,s,actor,command.claim_fact_id,contact);if(!valid.ok)return {false,{},valid.error};return {true,{command,std::move(reply.value)},{}};
}
Outcome<StableId> apply_authored_visit_reply_in_candidate(CommonStore& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const InteractionCatalog& definitions,const InteractionAccess& access,const VisitReplyCatalog& replies,VisitReplyState& state,const VisitReplyAuthorshipRead& read,const StableId& actor,const AuthoredVisitReply& command,const AuthoredVisitReplyQuote& quote){
    if(quote.command.intent_id!=command.intent_id||quote.command.message_fact_id!=command.message_fact_id||quote.command.received_fact_id!=command.received_fact_id||quote.command.claim_fact_id!=command.claim_fact_id)return {false,{},common_failure("VisitReplyAuthoredQuoteMismatch").error};auto fresh=preview_authored_visit_reply(common,messages,originals,definitions,access,replies,state,read,actor,command);if(!fresh.ok)return {false,{},fresh.error};auto written=apply_visit_reply_in_candidate(common,messages,originals,read.interactions,definitions,access,replies,state,actor,fresh.value.reply.command,quote.reply,read.life);if(!written.ok)return written;auto* row=state.posted.find(written.value);if(!row||row->player_receipt||row->authored_origin)return {false,{},common_failure("VisitReplyAuthoredWriteMismatch").error};row->authored_origin=VisitReplyAuthoredOrigin{command.intent_id,command.claim_fact_id};return written;
}
Status validate_visit_reply_authored_sources(const CommonStore& common,const VisitMessageCatalog& originals,const InteractionCatalog& definitions,const VisitReplyCatalog& replies,const VisitReplyState& state,const VisitReplyAuthorshipRead* read){
    if(!visit_reply_authored_version(state.version)){if(read)return common_failure("VisitReplyAuthoredVersionRequired");for(const auto& row:state.posted.rows())if(row.second.authored_origin)return common_failure("VisitReplyAuthoredVersionRequired",row.first);return common_success();}
    if(!visit_reply_authored_version(state.version)||!read||state.version!=replies.version)return common_failure("VisitReplyAuthorshipRequired");auto valid=validate_visit_reply_intents(read->intents,replies,read->reception,originals,definitions);if(!valid.ok)return valid;valid=validate_visit_reception_claims(common,read->claims,read->reception,originals,definitions,read->interactions,read->life?&read->life->messages.clock:nullptr,read->life?read->life->occupancy:nullptr);if(!valid.ok)return valid;
    // 即使所有请求缓存均已裁掉，也须从原控制链证明每次回复当时的实际producer身份。
    if(!read->player_before_fact)return common_failure("VisitReplyControlHistoryRequired");
    for(const auto& item:state.posted.rows()){const auto& row=item.second;auto player=read->player_before_fact(row.contact.tick,row.fact_id);if(!player.ok)return {false,{},player.error};if(player.value.empty()||!common.actor(player.value)||(row.authored_origin?player.value==row.contact.actor_id:player.value!=row.contact.actor_id))return common_failure("VisitReplyHistoricalProducerMismatch",row.fact_id);}
    for(const auto& item:state.collected.rows()){const auto& row=item.second;auto player=read->player_before_fact(row.contact.tick,row.fact_id);if(!player.ok)return {false,{},player.error};if(player.value!=row.contact.actor_id)return common_failure("VisitReplyHistoricalProducerMismatch",row.fact_id);}
    std::map<StableId,std::size_t> positions;std::size_t at=0;for(const auto& row:common.state().facts.rows())positions.emplace(row.first,at++);
    for(const auto& item:state.posted.rows()){const auto& row=item.second;if(!row.authored_origin)continue;if(row.player_receipt)return common_failure("VisitReplyAmbiguousProducer",row.fact_id);const auto& origin=*row.authored_origin;const auto s=source(*read,replies,originals,origin.intent_id);if(!s.intent||row.policy_id!=s.intent->reply_policy_id||row.response!=s.intent->response)return common_failure("VisitReplyAuthoredDeclarationMismatch",row.fact_id);valid=claim(common,*read,s,row.contact.actor_id,origin.reception_claim_fact_id,row.contact);if(!valid.ok)return valid;const auto before=visit_reply_detail::serial(origin.reception_claim_fact_id,visit_reception_claim_kind,common.state().next_instance_id),after=visit_reply_detail::serial(row.fact_id,visit_reply_posted_kind,common.state().next_instance_id);auto a=positions.find(origin.reception_claim_fact_id),b=positions.find(row.fact_id);if(!before||!after||*before>=*after||a==positions.end()||b==positions.end()||a->second>=b->second)return common_failure("VisitReplyAuthoredClaimOrderMismatch",row.fact_id);
    }return common_success();
}
}
